import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.CqGPl1zp.js";const n="/newx-doc/assets/%E6%96%87%E5%BF%83%E4%B8%80%E8%A8%80-%E5%AE%98%E6%96%B9.DwAaaRxi.png",y=JSON.parse('{"title":"【模型接入】文心一言","description":"","frontmatter":{},"headers":[],"relativePath":"ai/yiyan.md","filePath":"ai/yiyan.md","lastUpdated":null}'),d={name:"ai/yiyan.md"};function r(h,a,l,p,o,c){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="【模型接入】文心一言" tabindex="-1">【模型接入】文心一言 <a class="header-anchor" href="#【模型接入】文心一言" aria-label="Permalink to &quot;【模型接入】文心一言&quot;">​</a></h1><p>友情提示：</p><p>百度千帆 API 提供了 V2 版本，项目当前通过 OpenAI 兼容协议接入文本对话；图片、向量能力暂未接入。</p><p>项目基于 Spring AI + 自己实现的 <code>models/yiyan</code>，实现 <a href="https://yiyan.baidu.com/" target="_blank" rel="noreferrer">文心一言</a> 的接入，底层复用兼容 OpenAI 协议的客户端：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>ERNIE 5.1、ERNIE 5.0、ERNIE X1.1 等</td><td>YiYanChatModel</td></tr><tr><td>AI 绘画</td><td>暂未接入</td><td>暂未接入</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>由于文心一言是非开源的模型，所以无法私有化部署，需要去官网申请 API Key，然后通过项目自定义的 YiYanChatModel 接入。</p><h3 id="_1-1-申请百度云密钥" tabindex="-1">1.1 申请百度云密钥 <a class="header-anchor" href="#_1-1-申请百度云密钥" aria-label="Permalink to &quot;1.1 申请百度云密钥&quot;">​</a></h3><p>① 在 <a href="https://cloud.baidu.com/" target="_blank" rel="noreferrer">百度智能云</a> 上，注册一个账号。</p><p>② 在百度智能云的 <a href="https://console.bce.baidu.com/iam/#/iam/apikey/list" target="_blank" rel="noreferrer">API Key 管理</a> 页面，直接创建 API Key。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”（例如 <code>bce-v3/ALTAK-xxx/xxx</code>），不需要填写“自定义 API URL”（默认使用千帆 V2 地址）。</p><p><img src="'+n+`" alt="官方的密钥配置"></p><p>友情提示：</p><p>千帆 V2 使用 IAM Bearer Token 鉴权，只需要 API Key，不需要 Secret Key，也不需要创建应用。</p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型。</p><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>ernie-5.1</code></td><td>65536</td></tr><tr><td><code>ernie-5.0</code></td><td>65536</td></tr><tr><td><code>ernie-x1.1</code></td><td>65536</td></tr></tbody></table><h3 id="_2-2-ai-绘画" tabindex="-1">2.2 AI 绘画 <a class="header-anchor" href="#_2-2-ai-绘画" aria-label="Permalink to &quot;2.2 AI 绘画&quot;">​</a></h3><p>暂未接入。</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 YiYanChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.yiyan</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    yiyan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 文心一言</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${YIYAN_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ernie-5.1</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，YiYanChatModelTests 里有对应的测试用例，可以参考。</p>`,29)])])}const E=e(d,[["render",r]]);export{y as __pageData,E as default};
